import { useEffect, useRef } from "react";
import { View } from "react-native";
import { DragDropContentView } from "expo-drag-drop-content-view";
import { createStore, type StoreApi } from "zustand/vanilla";
import { useStore } from "zustand";
import { acceptsFile } from "@/components/nyc-tron/ui/components/files/drop-model";
import { DropZoneCopy, dropZoneClasses } from "@/components/nyc-tron/ui/components/files/DropZone.shared";
import type { DropZoneProps } from "@/components/nyc-tron/ui/components/files/DropZone.types";
import { space } from "@/components/nyc-tron/ui/tokens";

export type { DropAsset, DropAssets, DropZoneProps } from "@/components/nyc-tron/ui/components/files/DropZone.types";

type DropState={active:boolean};

/**
 * iOS and Android drop target over expo-drag-drop-content-view (optional peer,
 * needs a dev or production build; Expo Go does not include it). Drops come
 * from the system drag session: iPad and iPhone multitasking, Android split
 * screen and Samsung DeX. There is no browse control on native (see
 * FilePicker.native), so `browseLabel` and `disableObjectUrl` are ignored.
 * `accept` is applied to the dropped assets' names and types after the drop.
 */
export function DropZone({
  children,onDrop,onEnter,onExit,accept,allowedMimeTypes,includeBase64=false,
  disableObjectUrl:_disableObjectUrl,browseLabel:_browseLabel,onError:_onError,multiple:_multiple,disabled=false,
  title="Drop a file here",description,className,unstyled=false,style,...rest
}:DropZoneProps) {
  const storeRef=useRef<StoreApi<DropState>|null>(null);
  if(!storeRef.current)storeRef.current=createStore<DropState>(()=>({active:false}));
  const store=storeRef.current;
  const active=useStore(store,s=>s.active);
  // Unmounting the drop view on disable skips its onExit; end the drag here.
  useEffect(()=>{
    if(disabled&&store.getState().active){store.setState({active:false});onExit?.();}
  },[disabled,store,onExit]);
  const content=children??<DropZoneCopy title={title} description={description} unstyled={unstyled}/>;
  return (
    // No label on the container: iOS ignores it on a non-accessible view, and
    // making the view accessible would hide the content from VoiceOver. The
    // visible title is read in place.
    <View {...rest} style={style}
      {...{className:dropZoneClasses({active,disabled,unstyled,className})}}>
      {disabled ? content : (
        <DragDropContentView
          includeBase64={includeBase64}
          allowedMimeTypes={allowedMimeTypes}
          onEnter={()=>{store.setState({active:true});onEnter?.();}}
          onExit={()=>{store.setState({active:false});onExit?.();}}
          onDrop={({assets})=>{
            store.setState({active:false});
            onDrop?.({assets:assets.filter(a=>a.text!==undefined&&!a.uri
              ? !accept
              : acceptsFile({fileName:a.fileName,type:a.type},accept))});
          }}
          // Fills the well so the whole bordered area accepts the drop.
          style={{alignSelf:"stretch",alignItems:"center",justifyContent:"center",gap:space[3],flexGrow:1}}>
          {content}
        </DragDropContentView>
      )}
    </View>
  );
}

import type { ReactNode } from "react";
import { Text, View } from "react-native";
import { joinClasses } from "@/components/nyc-tron/ui/components/styles";

/** Well recipe shared by both forks. `active` is a drag over the zone. */
export function dropZoneClasses({active,disabled,unstyled,className}:{
  active:boolean;disabled:boolean;unstyled:boolean;className?:string;
}):string {
  return joinClasses("items-center justify-center",
    !unstyled&&"gap-3 rounded-card border-2 p-6",
    !unstyled&&(active?"border-solid border-focus bg-surface-sunken":"border-dashed border-border bg-surface-raised"),
    !unstyled&&"motion-reduce:transition-none",
    disabled&&"opacity-50",className);
}

/** Default content: headline, optional description and the web browse control. */
export function DropZoneCopy({title,description,browse,unstyled}:{
  title:string;description?:string;browse?:ReactNode;unstyled:boolean;
}) {
  return (
    <>
      <Text {...{className:joinClasses("text-center",!unstyled&&"text-base font-semibold leading-6 text-text")}}>{title}</Text>
      {description ? <Text {...{className:joinClasses("text-center",!unstyled&&"max-w-sm text-sm leading-5 text-text-muted")}}>{description}</Text> : null}
      {browse ? <View {...{className:!unstyled?"mt-1":undefined}}>{browse}</View> : null}
    </>
  );
}

import type { ReactNode } from "react";
import type { ViewProps } from "react-native";

/** Same shape as expo-drag-drop-content-view's DropAsset, so one handler serves both platforms. */
export interface DropAsset {
  /** Native: the app cache file URI. Web: a blob URL unless `disableObjectUrl`. */
  uri?:string;
  type:string;
  /** Data URL, only with `includeBase64`. */
  base64?:string;
  /** Native only: the original file path. */
  path?:string;
  /** Web only: the dropped or picked File. */
  file?:File;
  width?:number;
  height?:number;
  fileName?:string;
  /** Plain-text drops. */
  text?:string;
  /** Web only: revokes the blob URL. The app calls it when done with `uri`. */
  release?:()=>void;
}
export interface DropAssets {assets:DropAsset[]}

/** Props for DropZone. Drop-in for Nitro Forge's `StudioDropZoneProps`. */
export interface DropZoneProps extends Omit<ViewProps,"children"> {
  /** Replaces the default copy and browse control. */
  children?:ReactNode;
  /** One call per drop (or web pick), after `accept` and `allowedMimeTypes` filtering. */
  onDrop?:(event:DropAssets)=>void;
  /** A drag carrying content entered the zone. */
  onEnter?:()=>void;
  /** The drag left, was dropped or was cancelled. */
  onExit?:()=>void;
  /** Web: a dropped or picked file could not be read (base64). The others still arrive through `onDrop`. */
  onError?:(error:Error,file:File)=>void;
  /** Web: lets the built-in browse control pick several files. Drops always accept several. @default false */
  multiple?:boolean;
  /** HTML input syntax, e.g. ".docx,.nfd" or "image/*". Applied to drops and picks. */
  accept?:string;
  /** Exact strings or RegExps, as in expo-drag-drop-content-view. */
  allowedMimeTypes?:(string|RegExp)[];
  /** @default false */
  includeBase64?:boolean;
  /** Web only: skip creating blob URLs (the app reads `file` instead). @default false */
  disableObjectUrl?:boolean;
  disabled?:boolean;
  /** Default content headline. @default "Drop a file here" */
  title?:string;
  description?:string;
  /**
   * Web only: label of the file picker shown with the default content, the
   * path for people who cannot drag (WCAG 2.5.7). @default "Choose a file"
   */
  browseLabel?:string;
  className?:string;
  unstyled?:boolean;
}

import { useEffect, useRef, type ComponentRef } from "react";
import { View } from "react-native";
import { createStore, type StoreApi } from "zustand/vanilla";
import { useStore } from "zustand";
import { acceptsFile, dragDepth } from "@/components/nyc-tron/ui/components/files/drop-model";
import { DropZoneCopy, dropZoneClasses } from "@/components/nyc-tron/ui/components/files/DropZone.shared";
import { FilePicker } from "@/components/nyc-tron/ui/components/files/FilePicker.web";
import type { DropAsset, DropZoneProps } from "@/components/nyc-tron/ui/components/files/DropZone.types";

export type { DropAsset, DropAssets, DropZoneProps } from "@/components/nyc-tron/ui/components/files/DropZone.types";

function readDataUrl(file:File):Promise<string> {
  return new Promise((resolve,reject)=>{
    const reader=new FileReader();
    reader.onerror=()=>reject(reader.error??new Error("Could not read "+file.name));
    reader.onload=()=>resolve(String(reader.result??""));
    reader.readAsDataURL(file);
  });
}
async function toAsset(file:File,includeBase64:boolean,disableObjectUrl:boolean):Promise<DropAsset> {
  const uri=disableObjectUrl?undefined:URL.createObjectURL(file);
  return {
    uri,type:file.type||"application/octet-stream",file,fileName:file.name,
    base64:includeBase64?await readDataUrl(file):undefined,
    release:uri?()=>URL.revokeObjectURL(uri):undefined,
  };
}

type DropState={active:boolean};

/**
 * Web drop target. React Native Web does not forward HTML drag events, so
 * the listeners attach to the view's own DOM node; nothing renders raw HTML.
 * The default content includes a FilePicker, the keyboard and pointer path
 * for people who cannot drag. Custom `children` must provide their own.
 *
 * expo-drag-drop-content-view's web build is not used: its 0.9.2 web bundle
 * ships JSX in a .js file, which Vite/Rolldown parse as plain JavaScript.
 */
export function DropZone({
  children,onDrop,onEnter,onExit,onError,multiple=false,accept,allowedMimeTypes,includeBase64=false,
  disableObjectUrl=false,disabled=false,title="Drop a file here",description,
  browseLabel="Choose a file",className,unstyled=false,...rest
}:DropZoneProps) {
  const host=useRef<ComponentRef<typeof View>>(null);
  const storeRef=useRef<StoreApi<DropState>|null>(null);
  if(!storeRef.current)storeRef.current=createStore<DropState>(()=>({active:false}));
  const store=storeRef.current;
  const active=useStore(store,s=>s.active);
  // Latest props for listeners that are attached once.
  const latest=useRef({onDrop,onEnter,onExit,onError,accept,allowedMimeTypes,includeBase64,disableObjectUrl,disabled});
  latest.current={onDrop,onEnter,onExit,onError,accept,allowedMimeTypes,includeBase64,disableObjectUrl,disabled};

  // A file that cannot be read is reported and skipped; the rest still arrive.
  const deliver=async(files:File[],text?:string)=>{
    const p=latest.current;
    const kept=files.filter(file=>acceptsFile({fileName:file.name,type:file.type},p.accept,p.allowedMimeTypes));
    const settled=await Promise.allSettled(kept.map(file=>toAsset(file,p.includeBase64,p.disableObjectUrl)));
    const assets:DropAsset[]=[];
    settled.forEach((result,i)=>{
      if(result.status==="fulfilled")assets.push(result.value);
      else p.onError?.(result.reason instanceof Error?result.reason:new Error("Could not read "+kept[i]!.name),kept[i]!);
    });
    if(!assets.length&&!files.length&&text&&!p.accept&&acceptsFile({type:"text"},undefined,p.allowedMimeTypes)){
      assets.push({type:"text",text});
    }
    p.onDrop?.({assets});
  };

  // Becoming disabled mid-drag ends the drag: the next one must report its own enter.
  const depthRef=useRef(0);
  useEffect(()=>{
    if(disabled&&store.getState().active){depthRef.current=0;store.setState({active:false});latest.current.onExit?.();}
  },[disabled,store]);

  useEffect(()=>{
    const node=host.current as unknown as HTMLElement|null;
    if(!node||typeof node.addEventListener!=="function")return;
    const edge=(next:{depth:number;edge:"enter"|"exit"|null})=>{
      depthRef.current=next.depth;
      if(next.edge==="enter"){store.setState({active:true});latest.current.onEnter?.();}
      if(next.edge==="exit"){store.setState({active:false});latest.current.onExit?.();}
    };
    // dragover and drop are always cancelled: a disabled zone must still stop
    // the browser from opening the dropped file in place of the app.
    const enter=(e:DragEvent)=>{if(latest.current.disabled)return;e.preventDefault();edge(dragDepth(depthRef.current,"enter"));};
    const over=(e:DragEvent)=>{
      e.preventDefault();
      if(e.dataTransfer)e.dataTransfer.dropEffect=latest.current.disabled?"none":"copy";
    };
    const leave=(e:DragEvent)=>{if(latest.current.disabled)return;e.preventDefault();edge(dragDepth(depthRef.current,"leave"));};
    const drop=(e:DragEvent)=>{
      e.preventDefault();
      if(latest.current.disabled)return;
      edge(dragDepth(depthRef.current,"drop"));
      const files=Array.from(e.dataTransfer?.files??[]);
      void deliver(files,e.dataTransfer?.getData("text/plain"));
    };
    node.addEventListener("dragenter",enter);
    node.addEventListener("dragover",over);
    node.addEventListener("dragleave",leave);
    node.addEventListener("drop",drop);
    return ()=>{
      node.removeEventListener("dragenter",enter);
      node.removeEventListener("dragover",over);
      node.removeEventListener("dragleave",leave);
      node.removeEventListener("drop",drop);
    };
  },[store]);

  return (
    <View {...rest} ref={host} role="group" aria-label={rest["aria-label"]??title}
      aria-disabled={disabled||undefined}
      {...{className:dropZoneClasses({active,disabled,unstyled,className})}}>
      {children ?? <DropZoneCopy title={title} description={description} unstyled={unstyled}
        browse={<FilePicker label={browseLabel} accept={accept} multiple={multiple} disabled={disabled}
          onFiles={files=>void deliver(files)}/>}/>}
    </View>
  );
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

